import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"澤風大過","description":"周易折中 - 澤風大過","frontmatter":{"title":"澤風大過","description":"周易折中 - 澤風大過"},"headers":[],"relativePath":"classics/zhezhong/034.md","filePath":"classics/zhezhong/034.md"}'),h={name:"classics/zhezhong/034.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="澤風大過" tabindex="-1">澤風大過 <a class="header-anchor" href="#澤風大過" aria-label="Permalink to “澤風大過”">​</a></h1><h3 id="程傳" tabindex="-1">程傳 <a class="header-anchor" href="#程傳" aria-label="Permalink to “程傳”">​</a></h3><p>大過序卦：“頤者，養也。不養則不可動，故受之以大過。凡物養而後能成，成則能動，動則有過。大過所以次頤也。為卦上兌下巽，澤在木上，滅木也。澤者，潤養於木，乃至滅沒於木，為大過之義。大過者，陽過也，故為大者過，過之大與大事過也。聖賢道德功業大過於人，凡事之大過於常者皆是也。夫聖人盡人道，非過於理也。其制事以天下之正理，矯時之用小過於中者，則有之，如行過乎恭，喪過乎哀，用過乎儉是也。蓋矯之小過，而後能及於中，乃求中之用也。所謂大過者，常事之大者耳，非有過於理也。惟其大，故不常見，以其比常所見者大，故謂之大過。如堯舜之禪讓，湯武之放伐，皆由道也，道無不中，無不常，以世人所不常見，故謂之大過於常也。”</p><p>大過：棟橈，利有攸往，亨</p><h3 id="本義" tabindex="-1">本義 <a class="header-anchor" href="#本義" aria-label="Permalink to “本義”">​</a></h3><p>大陽也，四陽居中過盛，故為大過。上下二陰不勝其重，故有棟橈之象。又以四陽雖過，而二五得中，內巽外說，有可行之道，故利有所往而得亨也。</p><h3 id="程傳-1" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-1" aria-label="Permalink to “程傳”">​</a></h3><p>小過陰過於上下，大過陽過於中。陽過於中而上下弱矣，故為棟橈之象。棟取其勝重，四陽聚於中可謂重矣。九三、九四皆取棟象，謂任重也。橈取其本末弱，中強而本末弱，是以橈也。陰弱而陽強，君子盛而小人衰，故利有攸往而亨也。棟，今人謂之檁。</p><h3 id="集說" tabindex="-1">集說 <a class="header-anchor" href="#集說" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏宗傳曰 ：天下之事固有正理，豈可過耶？然古今固有所謂非常之事者，以理而論，亦無非君子之時中。特其事大𫝑重，不常見爾。</p></li><li><p>朱子語類 ：問大過、小過，先生與伊川之說不同。曰然，伊川此論正如以反經合道為非相似。殊不知大過自有大過時節，小過自有小過時節。處大過之時，則當為大過之事；處小過之時，則當為小過之事。在事雖是過，然適當其時，合當如此作，便是合義。</p></li><li><p>胡氏一桂曰 ：或疑頤與大過對者也，何不名為小過？中孚與小過對者也，何不名為大過？蓋大過以四陽在中言，小過以四陰在外言。此是聖人內陽外陰之意。</p></li><li><p>胡氏炳文曰 ：既曰棟橈，又曰利有攸往亨，何也？曰：棟橈以卦象言也，利往而後亨，是不可無大有為之才。而天下亦無不可為之事，以佔言也。</p></li><li><p>何氏楷曰 ：棟，《說文》謂之極，《爾雅》謂之桴，其義皆訓中也。即屋之脊檁。惟大過是以棟橈，是以利有攸往，惟有攸往，是以亨。翼傳乃字當玩。卦辭言棟，概指二三四五言也；爻辭專及三四者，舉中樞也。</p></li></ul><p>象曰：澤滅木，大過；君子以獨立不懼，遁世無悶</p><h3 id="本義-1" tabindex="-1">本義 <a class="header-anchor" href="#本義-1" aria-label="Permalink to “本義”">​</a></h3><p>澤滅於木，大過之象也。不懼無悶，大過之行也。</p><h3 id="程傳-2" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-2" aria-label="Permalink to “程傳”">​</a></h3><p>澤潤養於木者也，乃至滅沒於木，則過甚矣，故為大過。君子觀大過之象，以立其大過人之行。君子所以大過人者，以其能獨立不懼，遁世無悶也。天下非之而不顧，獨立不懼也；舉世不見知而不悔，遁世無悶也。如此然後能自守，所以為大過人也。</p><h3 id="集說-1" tabindex="-1">集說 <a class="header-anchor" href="#集說-1" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>劉氏牧曰 ：用之則獨立不懼，舍之則遁世無悶。</p></li><li><p>趙氏汝梅曰 ：獨立如巽木，無悶如兌說。</p></li><li><p>李氏簡曰 ：君子進則大有為，獨立不懼可也；或退而窮居，則堅貞不移，遁世無悶可也。皆大過之事。</p></li></ul><p>彖曰：大過，大者過也</p><h3 id="本義-2" tabindex="-1">本義 <a class="header-anchor" href="#本義-2" aria-label="Permalink to “本義”">​</a></h3><p>以卦體釋卦名義。</p><h3 id="程傳-3" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-3" aria-label="Permalink to “程傳”">​</a></h3><p>大者過，謂陽過也。在事為事之大者過，與其過之大。</p><h3 id="集說-2" tabindex="-1">集說 <a class="header-anchor" href="#集說-2" aria-label="Permalink to “集說”">​</a></h3><ul><li>俞氏琰曰：大過謂陽之過也。在人事，則泛言萬事大者之過，凡大者皆是非一端也。</li></ul><p>棟橈，本末弱也</p><h3 id="本義-3" tabindex="-1">本義 <a class="header-anchor" href="#本義-3" aria-label="Permalink to “本義”">​</a></h3><p>復以卦體釋卦辭。本謂初，末謂上，弱謂陰柔。</p><h3 id="程傳-4" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-4" aria-label="Permalink to “程傳”">​</a></h3><p>謂上下二陰衰弱，陽盛則陰衰，故為大者過。在小過則曰小者過，陰過也。</p><h3 id="集說-3" tabindex="-1">集說 <a class="header-anchor" href="#集說-3" aria-label="Permalink to “集說”">​</a></h3><ul><li>何氏楷曰：剛過始致本末之弱。本末既弱，剛亦不能獨支。本末弱即大過之象，乃棟所由橈也。</li></ul><p>剛過而中巽而說，行利有攸往，乃亨</p><h3 id="本義-4" tabindex="-1">本義 <a class="header-anchor" href="#本義-4" aria-label="Permalink to “本義”">​</a></h3><p>又以卦體、卦德釋卦辭。</p><h3 id="程傳-5" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-5" aria-label="Permalink to “程傳”">​</a></h3><p>言卦才之善也。剛雖過而二五皆得中，是處不失中道也。下巽上兌，是以巽順和說之道而行也。在大過之時，以中道巽說而行，故利有攸往，乃所以能亨也。</p><h3 id="集說-4" tabindex="-1">集說 <a class="header-anchor" href="#集說-4" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>朱氏震曰：剛過而中，所謂時中也。過非過於理也，以過為中也。猶之治疾，疾勢沈痼，必攻之以瞑眩之藥。自其治微疾之道視之，則謂之過；自藥病相對言之，則謂之中。大過之時，君子過越常分以濟弱，能達乎時中矣。</p></li><li><p>項氏安世曰：“棟橈”二字以六爻之象言之，中四爻強，初上二爻弱，有棟橈之象，此禍變之大者也。“利有攸往亨”以六爻之才言之，中四爻剛雖大過，而得時措之中，初上二爻又能巽而說，不失人心，故利於有行，雖遇大變而可以亨。此才略之大者也。“巽而說”之下加“行”字者，能以巽說而行，是以利有攸往也。又曰：先言亨後言利有攸往者，亨自亨利，自利也。今先言利有攸往後言亨者，明亨因於往也。故彖曰“利有攸往乃亨”，言往乃亨，不往則不亨也。</p></li></ul><p>大過之時大矣哉</p><h3 id="本義-5" tabindex="-1">本義 <a class="header-anchor" href="#本義-5" aria-label="Permalink to “本義”">​</a></h3><p>大過之時，非有大過人之材不能濟也，故嘆其大。</p><h3 id="程傳-6" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-6" aria-label="Permalink to “程傳”">​</a></h3><p>大過之時，其事甚大，故贊之曰大矣哉。如立非常之大事，興不世之大功，成絕俗之大德，皆大過之事也。</p><h3 id="集說-5" tabindex="-1">集說 <a class="header-anchor" href="#集說-5" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>胡氏炳文曰：大過之事甚大，無其時不可過，有其時無其才愈不可過。</p></li><li><p>蔡氏清曰：大過之時，非時大過也，人當大過之時也。以其時事宜於大過也，其理正小過所謂過以利貞與時行者也。大過二字屬人。</p></li></ul><p>初六：藉用白茅，無咎</p><h3 id="本義-6" tabindex="-1">本義 <a class="header-anchor" href="#本義-6" aria-label="Permalink to “本義”">​</a></h3><p>當大過之時，以陰柔居巽下，過於畏慎而無咎者也。故其象佔如此。白茅，物之潔者。</p><h3 id="程傳-7" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-7" aria-label="Permalink to “程傳”">​</a></h3><p>初以陰柔巽體而處下，過於畏慎者也。以柔在下，用茅藉物之象，不錯諸地而藉以茅，過於慎也，是以無咎。茅之為物，雖薄而用可重，以用之能成敬慎之道也。慎守斯術而行，豈冇失乎大過之用也？繫辭雲：“苟錯諸地而可矣，藉之用茅，何咎之有？”慎之至也。夫茅之為物，薄而用可重也。慎斯術也以往，其無所失矣。言敬慎之至也。茅雖至薄之物，然用之可甚重，以之藉薦則為重慎之道，是用之重也。人之過於敬慎，為之非難，而可以保其安而無過。苟能慎斯道，推而行之於事，其無所失矣。</p><h3 id="集說-6" tabindex="-1">集說 <a class="header-anchor" href="#集說-6" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>胡氏瑗曰 ：為事之始，不可輕易，必須恭慎，然後可以免咎。況居大過之時，是其事至重，功業至大，尤不易於有為，必當過分而慎重，然後可也。苟於事始慎之如此，則可以立天下之大功，興天下之大利，又何咎之有哉？</p></li><li><p>朱氏震曰 ：茅之為物，薄而用重，過慎也。過慎者，慎之至也。大過君子將有事焉，以任至大之事，過而無咎者，其惟過於慎乎？過非正也，初六執柔處下，不犯乎剛，於此而過，其誰咎之？</p></li><li><p>趙氏玉泉曰 ：當過時而陰居巽下，是以過慎之心任事，謹始慮終，無所不至。如物措諸地，又藉之以白茅焉。如是，則視天下無可忽之事者，舉天下無不可為之事，身無過動，行無敗謀，何咎之有？</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>胡氏、朱氏、趙氏說極於卦義相關。蓋大過者，大事之卦也。自古任大事者，必以小心為基。故聖人於初爻發義，任重大者棟也，基細微者茅也。棟支於上，茅藉於下，故系傳雲：“茅之為物，薄而用可重也。”正對棟為重物、重任而言。</p><p>象曰：藉用白茅，柔在下也</p><h3 id="程傳-8" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-8" aria-label="Permalink to “程傳”">​</a></h3><p>以陰柔處卑下之道，唯當過於敬慎而已。以柔在下為以茅藉物之象，敬慎之道也。</p><h3 id="集說-7" tabindex="-1">集說 <a class="header-anchor" href="#集說-7" aria-label="Permalink to “集說”">​</a></h3><ul><li>錢氏志立曰 ：以卦象論之，初與四應而在下，初者四之本也。本弱而藉茅，則敬慎之至，以善處者，故四之棟不至於傾也。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>高以下為基，剛以柔為本，柔在下對剛在上。</p><p>九二：枯楊生稊，老夫得其女妻，無不利</p><h3 id="本義-7" tabindex="-1">本義 <a class="header-anchor" href="#本義-7" aria-label="Permalink to “本義”">​</a></h3><p>陽過之始而比初陰，故其象佔如此。稊，根也，榮於下者也。榮於下則生於上矣。夫雖老而得女妻，猶能成生育之功也。</p><h3 id="程傳-9" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-9" aria-label="Permalink to “程傳”">​</a></h3><p>陽之大過比陰，則合，故二與五皆有生象。九二當大過之初，得中而居柔，與初密比而相與。初既切比於二，二復無應於上，其相與可知。是剛過之人而能以中自處，用柔相濟者也。過剛則不能有所為，九三是也；得中用柔，則能成大過之功，九二是也。楊者，陽氣易感之物，陽過則枯矣。楊枯槁而復生稊，陽過而未至於極也。九二陽過而與初，老夫得女妻之象。老夫而得女妻，則能成生育之功。二得中居柔而與初，故能復生稊而無過極之失，無所不利也。在大過，陽爻居陰則善，二與四是也。二不言吉，方言無所不利，未遽至吉也。稊，根也。劉琨《勸進表》雲：“生繁華於枯荑。”謂枯根也。鄭康成《易》亦作“荑”字，與稊同。</p><h3 id="集說-8" tabindex="-1">集說 <a class="header-anchor" href="#集說-8" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>司馬氏光曰 ：大過，剛已過矣，止可濟之以柔，不可濟之以剛也。故大過之時，皆以居陰為吉，不以得位為美。</p></li><li><p>楊氏時曰 ：聞之蜀僧雲，四爻之剛雖同為木，然或為楊，或為棟。棟負眾榱，則木之強者也；楊為早凋，則木之弱者也。此卦本末皆弱，二近於本，五近於末，故均為木之弱也。</p></li><li><p>項氏安世曰 ：二五皆濱於澤，楊，澤木也。當大過之時，故稱枯焉。過則木枯也。</p></li><li><p>王氏申子曰 ：大過諸爻，以剛柔適中者為善。初以柔居剛，二以剛居柔而比之，是剛柔適中，相濟而有功者也。其陽過也，如楊之枯，如夫之老；其相濟而有功也，如枯楊而生稊，如老夫得女妻。言陽雖過矣，九二處之得中，故無不利。</p></li><li><p>胡氏炳文曰 ：巽為木，兌為澤，楊近澤之木，故以取象。枯楊，大過象；稊，初在下象；老夫，九象；女妻，初柔在下象。九二陽雖過，而下比於陰，如枯楊雖過於老，稊榮於下則復生於上矣。老夫而得女妻，雖過以相與，終能成生育之功。無他，以陽從陰，過而不過生道也。</p></li></ul><p>象曰：老夫女妻，過以相與也</p><h3 id="程傳-10" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-10" aria-label="Permalink to “程傳”">​</a></h3><p>老夫之說少女，少女之順老夫，其相與過於常分，謂九二初六陰陽相與之和過於常也。</p><h3 id="集說-9" tabindex="-1">集說 <a class="header-anchor" href="#集說-9" aria-label="Permalink to “集說”">​</a></h3><ul><li>王氏申子曰 ：老夫而女妻，雖過乎常，然陰陽相與以成生育之功，則無不利也。</li></ul><p>九三：棟橈，兇</p><h3 id="本義-8" tabindex="-1">本義 <a class="header-anchor" href="#本義-8" aria-label="Permalink to “本義”">​</a></h3><p>三四二爻居卦之中，棟之象也。九三以剛居剛，不勝其重，故象橈而佔兇。</p><h3 id="程傳-11" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-11" aria-label="Permalink to “程傳”">​</a></h3><p>夫居大過之時，興大過之功，立大過之事，非剛柔得中，取於人以自輔，則不能也。既過於剛強，則不能與人同常，常之功尚不能獨立，況大過之事乎？以聖人之才，雖小事必取於人，當天下之大任，則可知矣。九三以大過之陽，復以剛自居而不得中，剛過之甚者也。以過甚之剛動，則違於中和而拂於眾心，安能當大過之任乎？故不勝其任，如棟之橈，傾敗其室，是以兇也。取棟為象者，以其無輔而不能勝重任也。或曰：“三巽體而應於上，豈無用柔之象乎？”曰：“言易者貴乎識𫝑之重輕，時之變易。三居過而用剛，巽既終而且變，豈復有用柔之義？應者，謂志相從也。三方過剛，上能系其志乎？”</p><h3 id="集說-10" tabindex="-1">集說 <a class="header-anchor" href="#集說-10" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>俞氏琰曰 ：卦有四剛爻，而九三過剛特甚，故以卦之棟橈屬之。</p></li><li><p>呉氏曰 ：九三棟橈，自橈也。所謂“太剛則折”，故彖有取於“剛過而中，巽而說行”也。</p></li></ul><p>象曰：棟橈之兇，不可以有輔也</p><h3 id="程傳-12" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-12" aria-label="Permalink to “程傳”">​</a></h3><p>剛強之過則不能取於人，人亦不能親輔之，如棟橈折不可支輔也。棟當室之中，不可加助，是不可以有輔也。</p><h3 id="集說-11" tabindex="-1">集說 <a class="header-anchor" href="#集說-11" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>楊氏時曰 ：棟居中而眾材輔之者也。九三以剛居剛，過而不中，剛過而不中則不可以有輔，此棟之所以橈也。</p></li><li><p>項氏安世曰 ：全卦有棟橈之象，而九三乃獨有之；全卦有利往之象，而九二乃獨有之。蓋九二當剛過之時，獨能居柔而用中，在六爻之中獨此一爻不過，故無不利也。卦體本以中太強而本末弱，是以為橈。九三以剛居剛，在六爻之中獨此一爻為過，故棟愈橈而不可輔也。</p></li></ul><p>九四：棟隆，吉；有它吝</p><h3 id="本義-9" tabindex="-1">本義 <a class="header-anchor" href="#本義-9" aria-label="Permalink to “本義”">​</a></h3><p>以陽居陰，過而不過，故其象隆而佔吉。然下應初六，以柔濟之，則過於柔矣，故又戒以有它則吝也。</p><h3 id="程傳-13" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-13" aria-label="Permalink to “程傳”">​</a></h3><p>四居近君之位，當大過之任者也。居柔為能用柔相濟，既不過剛，則能勝其任，如棟之隆起，是以吉也。隆起取不下橈之義。大過之時，非陽剛不能濟，以剛處柔為得宜矣。若又與初六之陰相應，則過也。既剛柔得宜而志復應陰，是有它也，有它則有累於剛，雖未至於大害，亦可吝也。蓋大過之時，動則過也。有它，謂更有他志。吝，為不足之義，謂可少也。或曰：“二比初則無不利，四若應初則為吝，何也？”曰：“二得中而比於初，為以柔相濟之義；四與初為正應，志相系者也。九既居四，剛柔得宜矣，復牽繫於陰以害其剛，則可吝也。”</p><h3 id="集說-12" tabindex="-1">集說 <a class="header-anchor" href="#集說-12" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>劉氏牧曰 ：大過之時，陽爻皆以居陰為美。有應，則有它吝。</p></li><li><p>李氏過曰 ：下卦上實而下弱，下弱則上傾。故三居下卦之上而曰棟橈兇，言下弱而無助也。上卦上弱而下實，下實則可載。故四居上卦之下而曰棟隆吉，言下實而不橈也。此二爻當分上下體㸔。</p></li><li><p>胡氏炳文曰 ：屋以棟為中，三視四則在下，棟橈於下之象；四在上，棟隆於上之象。</p></li><li><p>呉氏曰 ：三四居卦之中，皆有棟象。三橈而四隆者，三以剛居剛，四以剛居柔也；三在下，四在上也；三於下卦為上實下虛，四於上卦為下實上虛也。</p></li></ul><p>象曰：棟隆之吉，不橈乎下也</p><h3 id="程傳-14" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-14" aria-label="Permalink to “程傳”">​</a></h3><p>棟隆起則吉，不橈曲以就下也，謂不下繫於初也。</p><p>九五：枯楊生華，老婦得其士夫，無咎無譽</p><h3 id="本義-10" tabindex="-1">本義 <a class="header-anchor" href="#本義-10" aria-label="Permalink to “本義”">​</a></h3><p>九五陽過之極，又比過極之陰，故其象佔皆與二反。</p><h3 id="程傳-15" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-15" aria-label="Permalink to “程傳”">​</a></h3><p>九五當大過之時，本以中正居尊位，然下尢應助，固不能成大過之功；而上比過極之陰，其所相濟者如枯楊之生華。枯楊下生根稊，則能復生，如大過之陽興成事功也；上生華秀，雖冇所發，無益於枯也。上六過極之陰，老婦也；五雖非少，比老婦則為壯矣，於五無所賴也。故反稱婦，得過極之陰得陽之相濟，不為無益也。以士夫而得老婦，雖無罪咎，殊非美也，故云“無咎無譽”。象復言其可醜也。</p><h3 id="集說-13" tabindex="-1">集說 <a class="header-anchor" href="#集說-13" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>沈氏該曰 ：九二比於初，近本也，生稊之象也；九五承於上，近未也，生華之象也。</p></li><li><p>何氏楷曰 ：生稊則生機方長，生華則洩且竭矣。二所與者初，初本也，又巽之主爻，為木、為長、為髙木。已過而復芽，又長且高，故有往亨之理。五所與者上，上末也，又兌之主爻，為毀折、為附決，皆非木之所宜。木已過而生華，又毀且折，理無久生已。</p></li></ul><p>象曰：枯楊生華，何可久也；老婦士夫，亦可醜也</p><h3 id="程傳-16" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-16" aria-label="Permalink to “程傳”">​</a></h3><p>枯楊不生根而生華，旋復枯矣，安能久乎？老婦而得士夫，豈能成生育之功，亦為可醜也。</p><h3 id="集說-14" tabindex="-1">集說 <a class="header-anchor" href="#集說-14" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>蘇氏軾曰 ：稊者顚而復櫱，反其始也；華者盈而畢發，速其終也。</p></li><li><p>項氏安世曰 ：二五皆無正應而過以與陰者也。二所與者初，初本也，故為稊。稊者，木根新生之芽也，過而復芽，故有往亨之理。五所與者上，上末也，故為華。木已過而生華，故無久生之理也。</p></li><li><p>王氏申子曰 ：木枯而華，是速其枯；老婦士夫，是過乎常而為柔邪所惑。</p></li><li><p>何氏楷曰 ：盛極將枯而又生華，以自秏竭，不能久矣。二以剛居柔，初以柔居剛，此未甚過者也，又在卦初，故過以相與可成生育之功。五以剛居剛，上以柔居柔，皆過者也，又在卦終，故陰陽相比祇以為醜。其相反如此。</p></li></ul><p>上六：過涉滅頂，兇；無咎</p><h3 id="本義-11" tabindex="-1">本義 <a class="header-anchor" href="#本義-11" aria-label="Permalink to “本義”">​</a></h3><p>處過極之地，才弱不足以濟，然於義為無咎矣。蓋段身成仁之事故，其象佔如此。</p><h3 id="程傳-17" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-17" aria-label="Permalink to “程傳”">​</a></h3><p>上六以陰柔處過極，是小人過常之極者也。小人之所謂大過，非能為大過人之事也，直過常越理，不恤危亡，履險蹈禍而已。如過涉於水，至滅沒其頂，其兇可知。小人狂躁以自禍，蓋其宜也，復將何尤？故曰無咎，言自為之無所怨咎也。因澤之象而取涉義。</p><h3 id="集說-15" tabindex="-1">集說 <a class="header-anchor" href="#集說-15" aria-label="Permalink to “集說”">​</a></h3><ul><li>錢氏志立曰 ：澤之滅木，上之所以㓕頂也。雖至㓕頂，然有不容不涉，即不得不過者。孔子所以觀卦象而有獨立不懼之思也。</li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>此爻程傳以為履險蹈禍之小人，本義以為殺身成仁之君子。本義之說固比程傳為長，然又有一說以為大過之極，事無可為者。上六柔為說主，則是能從容隨順而不為剛激，以益重其𫝑，故雖處過涉滅頂之兇而無咎也。如東京之季，範李之徒，適足以推波助瀾，非救時之道。況上六居無位之地，委蛇和順，如申屠蟠、郭泰者，君子弗非也。此說亦可並存。</p><p>象曰：過涉之兇，不可咎也</p><h3 id="程傳-18" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-18" aria-label="Permalink to “程傳”">​</a></h3><p>過涉至溺乃自為之，不可以有咎也，言無所怨咎。</p><h3 id="集說-16" tabindex="-1">集說 <a class="header-anchor" href="#集說-16" aria-label="Permalink to “集說”">​</a></h3><ul><li>蘇氏軾曰 ：過涉至於滅頂，將有所救也，勢不可救而徒犯其害，故兇。然其義則不可咎也。</li></ul><p>總論</p><ul><li><p>馮氏椅曰 ：易大抵上下畫停者，從中分反對為象，非他卦相應之例也。頤、中孚、小過皆然，而此卦尤明。三與四對，皆為棟象，上隆下橈也；二與五對，皆為枮楊之象，上革下稊也；初與上對，初為藉用白茅之慎，上為過涉滅頂之兇也。</p></li><li><p>龔氏煥曰 ：大過本為陽過，若復以陽居陽，則愈過矣。故諸爻以陽居陰者皆吉，以陽居陽者皆兇，與大壯諸爻取義略同。</p></li></ul>',123)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
